package leveling

import (
	"path/filepath"
	"testing"
)

// A guide build may not spend points on a talent that provably does nothing for the spec
// (sim-accuracy round 15, owner's talent adoption rule). Each row names the talents the
// spec's rotation can never touch:
//
//   - a cat casts no Arcane or Nature spell, so Nature's Focus ("your Arcane and Nature
//     spells ... not lose casting time") and Subtlety ("threat generated by your Nature and
//     Arcane spells") do nothing for it;
//   - a Restoration druid never casts Moonfire, and Improved Moonfire is the prerequisite
//     only of Vengeance, which the build does not take; Genesis 5, Moonglow 3 and Nature's
//     Majesty 2 already open Nature's Splendor's row;
//   - an Elemental shaman never swings a weapon, so Elemental Devastation ("your chance to
//     get a Critical Strike with melee attacks") does nothing for it; Trial by Fire (Fire
//     Nova and Magma Totem, which the rotation casts on two or more targets) is the toll
//     point that does something (sim-accuracy round 20);
//   - a Beast Mastery or Marksmanship hunter shoots and never melees, so the Survival
//     tree's melee-only talents do nothing for it; a Survival hunter fights in melee
//     (owner ruling) and casts no shot or sting, so the Marksmanship tree's ranged-only
//     talents do nothing for it. The three hunter builds spend nothing there (sim-accuracy
//     round 20, every point re-read against the 70755 talent text).
//   - a rogue on a boss never casts Expose Armor (it does not stack with Sunder Armor),
//     Kidney Shot (bosses are immune to stuns) or Riposte (the boss never attacks the
//     rogue), never dodges or resists for Setup, and no rogue opens with Ambush (every
//     pull is a Garrote), so Improved Expose Armor, Improved Kidney Shot, Riposte, Setup
//     and Improved Ambush do nothing for any rogue spec (sim-accuracy round 20, which
//     found no rogue build spending a point on them).
func TestGuideBuildsSpendNothingOnDeadTalents(t *testing.T) {
	rangedHunterDead := []string{"Savage Strikes", "Predator's Edge", "Expose Prey", "Counterattack", "Strider Kick", "Lacerating Strikes"}
	rogueDead := []string{"Improved Expose Armor", "Improved Kidney Shot", "Riposte", "Setup", "Improved Ambush"}
	cases := []struct {
		class string
		spec  string
		dead  []string
	}{
		{"druid", "feral", []string{"Nature's Focus", "Subtlety"}},
		{"druid", "restoration", []string{"Improved Moonfire"}},
		{"shaman", "elemental", []string{"Elemental Devastation"}},
		{"hunter", "beast-mastery", rangedHunterDead},
		{"hunter", "marksmanship", rangedHunterDead},
		{"hunter", "survival", []string{"Ranged Weapon Specialization", "Mortal Shots", "Barrage", "Improved Stings", "Sniper Shot"}},
		{"rogue", "assassination", rogueDead},
		{"rogue", "combat", rogueDead},
		{"rogue", "subtlety", rogueDead},
	}
	repoRoot := filepath.Join("..", "..")
	active, err := ReadActiveBuild(repoRoot)
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range cases {
		t.Run(tc.class+"-"+tc.spec, func(t *testing.T) {
			trees, err := LoadTalentTrees(repoRoot, active, tc.class)
			if err != nil {
				t.Fatal(err)
			}
			ids := make(map[string]int)
			for _, tree := range trees {
				for _, node := range tree.Talents {
					ids[node.Name] = node.ID
				}
			}
			builds := map[string]func(string, string, string) (string, [3]string, error){
				"build": GuideBuildTalents, "raidBuild": GuideRaidBuildTalents,
			}
			for line, read := range builds {
				_, digits, err := read(repoRoot, tc.class, tc.spec)
				if err != nil {
					t.Fatal(err)
				}
				targets := GuideTalentTargets(trees, digits)
				for _, name := range tc.dead {
					id, ok := ids[name]
					if !ok {
						t.Fatalf("no %s in the %s trees", name, tc.class)
					}
					if got := targets[id]; got != 0 {
						t.Errorf("the %s %s %s spends %d points on %s, want 0", tc.class, tc.spec, line, got, name)
					}
				}
			}
		})
	}
}

// The cat's level 60 build, once the caster points are gone, finishes Heart of the Wild
// (10% Strength in Cat Form).
func TestCatLevelSixtyBuildFinishesHeartOfTheWild(t *testing.T) {
	repoRoot := filepath.Join("..", "..")
	active, err := ReadActiveBuild(repoRoot)
	if err != nil {
		t.Fatal(err)
	}
	trees, err := LoadTalentTrees(repoRoot, active, "druid")
	if err != nil {
		t.Fatal(err)
	}
	_, digits, err := GuideBuildTalents(repoRoot, "druid", "feral")
	if err != nil {
		t.Fatal(err)
	}
	const feralTree, restorationTree = 1, 2
	targets := GuideTalentTargets(trees, digits)
	ranks, err := TalentRanksFromString(trees, LadderTalentString(trees, targets, feralTree, 60, ForSpec("druid-feral")))
	if err != nil {
		t.Fatal(err)
	}
	for _, node := range trees[restorationTree].Talents {
		if node.Name == "Heart of the Wild" && ranks[node.ID] != node.MaxRank {
			t.Errorf("the cat's level 60 build has Heart of the Wild %d, want %d", ranks[node.ID], node.MaxRank)
		}
	}
}

// Nature's Reach's client row (16819) carries melee hit (aura 54) as well as spell hit (aura
// 55), 4% at 2/2 with no class mask, and hit is the cat's second stat. Both cat builds take
// it (sim-accuracy round 15 wave 4: raid 60 +2.6 to +3.2%, bare 50 +1.7 to +1.9%).
func TestCatBuildsTakeNaturesReach(t *testing.T) {
	repoRoot := filepath.Join("..", "..")
	active, err := ReadActiveBuild(repoRoot)
	if err != nil {
		t.Fatal(err)
	}
	trees, err := LoadTalentTrees(repoRoot, active, "druid")
	if err != nil {
		t.Fatal(err)
	}
	var reach TalentNode
	for _, node := range trees[0].Talents {
		if node.Name == "Nature's Reach" {
			reach = node
		}
	}
	if reach.ID == 0 {
		t.Fatal("no Nature's Reach in the Balance tree")
	}
	for name, read := range map[string]func(string, string, string) (string, [3]string, error){
		"build":     GuideBuildTalents,
		"raidBuild": GuideRaidBuildTalents,
	} {
		_, digits, err := read(repoRoot, "druid", "feral")
		if err != nil {
			t.Fatal(err)
		}
		if got := GuideTalentTargets(trees, digits)[reach.ID]; got != reach.MaxRank {
			t.Errorf("the cat %s takes Nature's Reach %d, want %d", name, got, reach.MaxRank)
		}
	}
}

// Furor's bear half is 10 rage on a shift into Bear Form, which a tank in a fight never makes
// (the tank starts in Dire Bear Form; round 6 G0), while Naturalist is 2% damage, and so
// threat, a rank. The bear build keeps one Furor point and finishes Naturalist (sim-accuracy
// round 15 wave 8: threat +7.6 to +7.7% at raid and bare 60, chance of death unchanged; bands
// 30 to 50 +1.9 to +5.9%; band 20 -0.5% threat for 68-76% to 41-49% chance of death).
func TestBearBuildFinishesNaturalistOverFuror(t *testing.T) {
	repoRoot := filepath.Join("..", "..")
	active, err := ReadActiveBuild(repoRoot)
	if err != nil {
		t.Fatal(err)
	}
	trees, err := LoadTalentTrees(repoRoot, active, "druid")
	if err != nil {
		t.Fatal(err)
	}
	_, digits, err := GuideBuildTalents(repoRoot, "druid", "feral-bear")
	if err != nil {
		t.Fatal(err)
	}
	targets := GuideTalentTargets(trees, digits)
	for _, tree := range trees {
		for _, node := range tree.Talents {
			switch node.Name {
			case "Furor":
				if targets[node.ID] > 1 {
					t.Errorf("the bear build spends %d points on Furor, want at most 1", targets[node.ID])
				}
			case "Naturalist":
				if targets[node.ID] != node.MaxRank {
					t.Errorf("the bear build has Naturalist %d, want %d", targets[node.ID], node.MaxRank)
				}
			}
		}
	}
}
